      float s = position.y + .5; float4 c = lerp(ct, ch, s);
      c.xy += (nrm*position.x*uW*2. + dir*(s-.5)*uW)*2./uRes*c.w;
      gl_Position = c; vF = 1. - age/aT.y; vQ = v2(position.x*2., s);
    }

